import { useCallback, useEffect, useMemo, useState } from 'react'
import { api } from '../services/api.js'
import { useAuth } from '../auth/useAuth.js'
import { useClassSelection } from '../class/useClassSelection.js'
import { DataTable, Field, Message, PageIntro, Panel, Pill, ReadOnlyField } from '../components/ui.jsx'

export function ExamsPage() {
  const { user } = useAuth()
  const { selectedClassId, selectedClass } = useClassSelection()
  const isAdmin = useMemo(() => user?.role === 'admin', [user?.role])
  const [exams, setExams] = useState([])
  const [error, setError] = useState('')
  const [form, setForm] = useState({ name: '', date: '' })

  const load = useCallback(async () => {
    setError('')
    try {
      const res = await api.get('/exams', { params: selectedClassId ? { class_id: selectedClassId } : {} })
      setExams(res.data.exams || [])
    } catch (e) {
      setExams([])
      setError(e?.response?.data?.error || 'Failed to load exams')
    }
  }, [selectedClassId])

  useEffect(() => {
    load()
  }, [load])

  async function createExam(event) {
    event.preventDefault()
    setError('')
    try {
      await api.post('/exams', { ...form, class_id: Number(selectedClassId) })
      setForm({ name: '', date: '' })
      await load()
    } catch (e) {
      setError(e?.response?.data?.error || 'Failed to create exam')
    }
  }

  return (
    <div className="space-y-6">
      <PageIntro
        eyebrow="Exams"
        title={isAdmin ? 'Plan assessments with a cleaner flow' : 'Review the current exam schedule'}
        description={
          isAdmin
            ? 'Set up upcoming exams for the active class and keep academic timelines easier to scan.'
            : 'Students and teachers can review upcoming exam dates without digging through cluttered lists.'
        }
        action={selectedClass ? <Pill tone="amber">Class {selectedClass.class_name} • {selectedClass.section}</Pill> : null}
      />

      {error ? <Message>{error}</Message> : null}

      {isAdmin ? (
        <Panel title="Create exam" subtitle="Publish the exam name and schedule for the selected class.">
          <form onSubmit={createExam} className="grid grid-cols-1 gap-4 md:grid-cols-3">
            <Field label="Exam Name" value={form.name} onChange={(value) => setForm((current) => ({ ...current, name: value }))} placeholder="Midterm Science" />
            <ReadOnlyField label="Class & Section" value={selectedClass ? `Class ${selectedClass.class_name} - ${selectedClass.section}` : 'Select a class'} />
            <label className="field-shell">
              <span className="field-label">Date</span>
              <input type="date" value={form.date} onChange={(event) => setForm((current) => ({ ...current, date: event.target.value }))} className="field-input" />
            </label>
            <div className="md:col-span-3">
              <button className="app-button">Create exam</button>
            </div>
          </form>
        </Panel>
      ) : null}

      <Panel title="Exam schedule" subtitle="A calmer view of planned exams for the selected class.">
        <DataTable
          columns={['Name', 'Class', 'Date']}
          rows={exams}
          empty="No exams scheduled yet"
          renderRow={(exam) => (
            <tr key={exam.id}>
              <td className="font-semibold text-slate-900">{exam.name}</td>
              <td>{exam.class_name ?? exam.class}</td>
              <td>{String(exam.date).slice(0, 10)}</td>
            </tr>
          )}
        />
      </Panel>
    </div>
  )
}
